import pytest


def rotl8(x: int, k: int) -> int:
    """Rotate the 8-bit value x left by k bits, wrapping high bits around.

    x must be in 0..255 and k in 0..7; the result is in 0..255.
    """
    return ((x << k) | (x >> (8 - k))) & 0xFF


def test_rotl8_zero_shift() -> None:
    assert rotl8(0b10110001, 0) == 0b10110001
    assert rotl8(0, 0) == 0
    assert rotl8(255, 0) == 255


def test_rotl8_simple() -> None:
    assert rotl8(0b00000001, 1) == 0b00000010
    assert rotl8(0b00000001, 7) == 0b10000000


def test_rotl8_wraps_high_bits() -> None:
    assert rotl8(0b10000000, 1) == 0b00000001
    assert rotl8(0b10110001, 1) == 0b01100011
    assert rotl8(0b11000000, 2) == 0b00000011
    assert rotl8(0b10000001, 4) == 0b00011000


def test_rotl8_fixed_points() -> None:
    for k in range(8):
        assert rotl8(0, k) == 0
        assert rotl8(255, k) == 255
    assert rotl8(0b10101010, 2) == 0b10101010
    assert rotl8(0b01010101, 4) == 0b01010101


def test_rotl8_half_turn_is_nibble_swap() -> None:
    assert rotl8(0xAB, 4) == 0xBA
    assert rotl8(0x12, 4) == 0x21


def test_rotl8_result_in_range() -> None:
    for x in range(256):
        for k in range(8):
            assert 0 <= rotl8(x, k) <= 255


def test_rotl8_preserves_popcount() -> None:
    for x in range(256):
        for k in range(8):
            assert rotl8(x, k).bit_count() == x.bit_count()


def test_rotl8_composition() -> None:
    for x in range(256):
        for a in range(8):
            for b in range(8):
                assert rotl8(rotl8(x, a), b) == rotl8(x, (a + b) % 8)


def test_rotl8_inverse() -> None:
    for x in range(256):
        for k in range(1, 8):
            assert rotl8(rotl8(x, k), 8 - k) == x


def test_rotl8_matches_reference() -> None:
    for x in range(256):
        for k in range(8):
            expected = ((x << k) | (x >> (8 - k))) & 0xFF
            assert rotl8(x, k) == expected


@pytest.mark.parametrize(
    ("x", "k", "expected"),
    [
        (0x81, 1, 0x03),
        (0xF0, 4, 0x0F),
        (0x0F, 4, 0xF0),
        (0x01, 0, 0x01),
        (0x80, 7, 0x40),
    ],
)
def test_rotl8_parametrized(x: int, k: int, expected: int) -> None:
    assert rotl8(x, k) == expected

